    gilded_forgetuyereblock = { name = "Pozlačen blok šob za peč", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen blok šob za peč za kovace." },
    jewel_set_forgetuyereblock = { name = "Draguljast blok šob za peč", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast blok šob za peč za kovace." },
