    sovereign_forgetuyereblock_palace = { name = "Suverena forgetuyereblock palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
ForgeTuyereBlockMaker.ironStock=18; ForgeTuyereBlockMaker.bronzeStock=14; ForgeTuyereBlockMaker.woodStock=10; ForgeTuyereBlockMaker.leatherStock=8; ForgeTuyereBlockMaker.silverStock=8; ForgeTuyereBlockMaker.goldStock=6; ForgeTuyereBlockMaker.jewelStock=4; ForgeTuyereBlockMaker.pearlStock=4
ForgeTuyereBlockMaker.productStock = {}; ForgeTuyereBlockMaker.buildings = {}; ForgeTuyereBlockMaker.maker = nil; ForgeTuyereBlockMaker.activeMaking = {}; ForgeTuyereBlockMaker.totalProducts = 0; ForgeTuyereBlockMaker.dayTimer = 0
function ForgeTuyereBlockMaker.init() ForgeTuyereBlockMaker.ironStock=18; ForgeTuyereBlockMaker.bronzeStock=14; ForgeTuyereBlockMaker.woodStock=10; ForgeTuyereBlockMaker.leatherStock=8; ForgeTuyereBlockMaker.silverStock=8; ForgeTuyereBlockMaker.goldStock=6; ForgeTuyereBlockMaker.jewelStock=4; ForgeTuyereBlockMaker.pearlStock=4; ForgeTuyereBlockMaker.productStock={}; ForgeTuyereBlockMaker.buildings={}; ForgeTuyereBlockMaker.maker=nil; ForgeTuyereBlockMaker.activeMaking={}; ForgeTuyereBlockMaker.totalProducts=0; ForgeTuyereBlockMaker.dayTimer=0; print("[ForgeTuyereBlockMaker] Royal Forge Tuyere Block Maker System initialized (6 products, 4 buildings)") end
function ForgeTuyereBlockMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ForgeTuyereBlockMaker.maker={name=n or ("Blokirnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Blokirnik najet: %s (spretnost: %d)",ForgeTuyereBlockMaker.maker.name,s),"success") end; return true end
function ForgeTuyereBlockMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ForgeTuyereBlockMaker.build(id) local ok,e=ForgeTuyereBlockMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ForgeTuyereBlockMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ForgeTuyereBlockMaker.getQualityBonus() local b=0; for _,bd in ipairs(ForgeTuyereBlockMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ForgeTuyereBlockMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ForgeTuyereBlockMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ForgeTuyereBlockMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ForgeTuyereBlockMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ForgeTuyereBlockMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ForgeTuyereBlockMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ForgeTuyereBlockMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ForgeTuyereBlockMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ForgeTuyereBlockMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ForgeTuyereBlockMaker.buildings==0 then return false,"Potrebna blokna delavnica" end; if not ForgeTuyereBlockMaker.maker then return false,"Potreben blokirnik" end; return true end
function ForgeTuyereBlockMaker.make(pt,qty) qty=qty or 1; local ok,e=ForgeTuyereBlockMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ForgeTuyereBlockMaker.ironStock=ForgeTuyereBlockMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ForgeTuyereBlockMaker.bronzeStock=ForgeTuyereBlockMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ForgeTuyereBlockMaker.woodStock=ForgeTuyereBlockMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ForgeTuyereBlockMaker.leatherStock=ForgeTuyereBlockMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ForgeTuyereBlockMaker.silverStock=ForgeTuyereBlockMaker.silverStock-d.silverCost*qty end; if d.goldCost then ForgeTuyereBlockMaker.goldStock=ForgeTuyereBlockMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ForgeTuyereBlockMaker.jewelStock=ForgeTuyereBlockMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ForgeTuyereBlockMaker.pearlStock=ForgeTuyereBlockMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ForgeTuyereBlockMaker.maker then t=math.max(1,t-math.floor(ForgeTuyereBlockMaker.maker.skill/13)) end; table.insert(ForgeTuyereBlockMaker.activeMaking,{id="forgetuyereblock_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ForgeTuyereBlockMaker.completeMaking(m) local q=1.0+(ForgeTuyereBlockMaker.getQualityBonus()/100); if ForgeTuyereBlockMaker.maker then q=q+(ForgeTuyereBlockMaker.maker.skill/140) end; q=math.min(2.5,q); ForgeTuyereBlockMaker.productStock[m.productType]=(ForgeTuyereBlockMaker.productStock[m.productType] or 0)+m.quantity; ForgeTuyereBlockMaker.totalProducts=ForgeTuyereBlockMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ForgeTuyereBlockMaker.maker then ForgeTuyereBlockMaker.maker.itemsMade=ForgeTuyereBlockMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ForgeTuyereBlockMaker.maker.skill=math.min(100,ForgeTuyereBlockMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Blok izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"forgetuyereblock.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ForgeTuyereBlockMaker.update(dt) if not _G.state then return end; ForgeTuyereBlockMaker.dayTimer=ForgeTuyereBlockMaker.dayTimer+dt; if ForgeTuyereBlockMaker.dayTimer>=30 then ForgeTuyereBlockMaker.dayTimer=0; for i=#ForgeTuyereBlockMaker.activeMaking,1,-1 do local m=ForgeTuyereBlockMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ForgeTuyereBlockMaker.completeMaking(m); table.remove(ForgeTuyereBlockMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ForgeTuyereBlockMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ForgeTuyereBlockMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ForgeTuyereBlockMaker.getStats() return {ironStock=ForgeTuyereBlockMaker.ironStock,bronzeStock=ForgeTuyereBlockMaker.bronzeStock,woodStock=ForgeTuyereBlockMaker.woodStock,leatherStock=ForgeTuyereBlockMaker.leatherStock,silverStock=ForgeTuyereBlockMaker.silverStock,goldStock=ForgeTuyereBlockMaker.goldStock,jewelStock=ForgeTuyereBlockMaker.jewelStock,pearlStock=ForgeTuyereBlockMaker.pearlStock,productStock=ForgeTuyereBlockMaker.productStock,numBuildings=#ForgeTuyereBlockMaker.buildings,hasMaker=ForgeTuyereBlockMaker.maker~=nil,makerName=ForgeTuyereBlockMaker.maker and ForgeTuyereBlockMaker.maker.name or "—",makerSkill=ForgeTuyereBlockMaker.maker and ForgeTuyereBlockMaker.maker.skill or 0,activeMaking=#ForgeTuyereBlockMaker.activeMaking,totalProducts=ForgeTuyereBlockMaker.totalProducts} end
return ForgeTuyereBlockMaker
